// sealed interface Shape permits Circle, Square {}  +  record Circle(double radius) / record Square(double side)

static String collide(Shape a, Shape b) {
    return switch (a) {
        case Circle c -> switch (b) {
            case Square s -> "circle vs square";
            case Circle c2 -> "two circles";
        };
        case Square s -> switch (b) {
            case Circle c -> collide(c, s);   // canonicalise symmetric pairs
            case Square s2 -> "two squares";
        };
    };
}

