interface ShapeVisitor {
    void visit(Circle c);
    void visit(Square s);
}
abstract class Shape { abstract void accept(ShapeVisitor v); }
final class Circle extends Shape {
    final double radius;
    Circle(double radius) { this.radius = radius; }
    @Override void accept(ShapeVisitor v) { v.visit(this); }   // dispatch #2 target
}
